function mockArrivalPhotoDataUri(title, bg) {
  var svg =
    '<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200">' +
    '<rect width="200" height="200" fill="' + bg + '"/>' +
    '<text x="100" y="108" text-anchor="middle" font-family="Arial,sans-serif" font-size="14" fill="#fff">' +
    title + "</text></svg>";
  return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
}

(function initMockArrivalPhotoSampleUrls() {
  var samples = MOCK_ARRIVAL_PHOTO_SAMPLES;
  if (samples["arr-container-door"]) {
    samples["arr-container-door"].url = mockArrivalPhotoDataUri("\u96c6\u88c5\u7bb1\u67dc\u95e8", "#3d6b9e");
  }
  if (samples["arr-unloading"]) {
    samples["arr-unloading"].url = mockArrivalPhotoDataUri("\u5378\u8d27\u73b0\u573a", "#2d8a5e");
  }
  if (samples["arr-seal"]) {
    samples["arr-seal"].url = mockArrivalPhotoDataUri("\u5c01\u6761\u7279\u5199", "#b85c1a");
  }
})();

/** 按资源 id 克隆到仓拍照列表，供预约单 arrivalPhotos 挂载 */
function mockArrivalPhotosFromSampleIds(ids) {
  return (ids || []).map(function (id) {
    var sample = MOCK_ARRIVAL_PHOTO_SAMPLES[id];
    return sample ? JSON.parse(JSON.stringify(sample)) : null;
  }).filter(function (p) {
    return !!p;
  });
}

