/** 保证每条预约单均有打托字段和 arrivalPhotos 数组；演示单挂载到仓拍照 */
(function normalizeMockAppointmentExtras() {
  MOCK_DELIVERY_APPOINTMENT_LIST.forEach(function (a) {
    if (a.isPalletized == null) {
      a.isPalletized = Number(a.totalPallets) > 0;
    }
    if (a.estimatedCartons == null || a.estimatedCartons === "") {
      var cartons = 0;
      (a.inboundOrders || []).forEach(function (snap) {
        cartons += Number(snap.cartons) || 0;
      });
      a.estimatedCartons = cartons || "";
    }
    if (a.isPalletized === false) {
      a.totalPallets = "";
    }
    if (!Array.isArray(a.arrivalPhotos)) a.arrivalPhotos = [];
  });
  var demo = null;
  for (var i = 0; i < MOCK_DELIVERY_APPOINTMENT_LIST.length; i++) {
    if (MOCK_DELIVERY_APPOINTMENT_LIST[i].id === "appt-006") {
      demo = MOCK_DELIVERY_APPOINTMENT_LIST[i];
      break;
    }
  }
  if (demo && !demo.arrivalPhotos.length) {
    demo.arrivalPhotos = mockArrivalPhotosFromSampleIds([
      "arr-container-door",
      "arr-unloading"
    ]);
  }
})();

/**
 * 预约送仓时间流程改造 · 一次性数据清洗
 * - expectedInboundTime 统一为日期 "YYYY-MM-DD"（货代仅填日期）
 * - warehouseConfirmedInboundTime 统一为 "YYYY-MM-DD HH:MM--HH:MM"（仓库确认时段，同日）
 */
(function normalizeMockAppointmentTimeFormat() {
  function pickDatePart(str) {
    if (!str) return '';
    var s = String(str).trim();
    var head = s.split('~')[0].trim();
    var m = head.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);
    if (!m) return '';
    var mm = m[2].length === 1 ? '0' + m[2] : m[2];
    var dd = m[3].length === 1 ? '0' + m[3] : m[3];
    return m[1] + '-' + mm + '-' + dd;
  }

  function pickHHMM(str) {
    if (!str) return '';
    var m = String(str).match(/(\d{1,2}):(\d{2})/);
    if (!m) return '';
    var hh = m[1].length === 1 ? '0' + m[1] : m[1];
    return hh + ':' + m[2];
  }

  function addHours(hhmm, hours) {
    if (!hhmm) return '';
    var parts = hhmm.split(':');
    var h = parseInt(parts[0], 10) + hours;
    if (h > 23) h = 23;
    var hh = h < 10 ? '0' + h : String(h);
    return hh + ':' + parts[1];
  }

  function cleanExpected(str) {
    if (!str) return '';
    return pickDatePart(str);
  }

  function cleanWarehouseSlot(str) {
    if (!str) return '';
    var s = String(str).trim();
    if (s.indexOf('--') !== -1) {
      return s;
    }
    if (s.indexOf('~') !== -1) {
      var parts = s.split('~');
      var leftDate = pickDatePart(parts[0]);
      var leftHHMM = pickHHMM(parts[0]) || '09:00';
      var rightDate = pickDatePart(parts[1]);
      var rightHHMM = pickHHMM(parts[1]) || '17:00';
      if (!leftDate) return '';
      var endHHMM = (rightDate === leftDate || !rightDate) ? rightHHMM : '23:59';
      if (endHHMM <= leftHHMM) endHHMM = addHours(leftHHMM, 2);
      return leftDate + ' ' + leftHHMM + '--' + endHHMM;
    }
    var date = pickDatePart(s);
    var hhmm = pickHHMM(s);
    if (!date) return '';
    if (!hhmm) hhmm = '09:00';
    return date + ' ' + hhmm + '--' + addHours(hhmm, 2);
  }

  MOCK_DELIVERY_APPOINTMENT_LIST.forEach(function (a) {
    a.expectedInboundTime = cleanExpected(a.expectedInboundTime);
    a.warehouseConfirmedInboundTime = cleanWarehouseSlot(a.warehouseConfirmedInboundTime);
    if (typeof a.remark !== 'string') a.remark = '';
    if (!Array.isArray(a.operationLogs)) a.operationLogs = [];
  });
})();

